                          className={
                            "h-full rounded-full " +
                            (pct >= 80 ? "bg-emerald-500" : pct >= 50 ? "bg-amber-500" : "bg-rose-500")
                          }
                          style={{ width: `${pct}%` }}
                        />
                      </div>
                    </div>
                  </TableCell>
