import fs from 'fs';
import Papa from 'papaparse';
import { differenceInDays, parseISO } from 'date-fns';

const csv = fs.readFileSync('/Users/btoomey/newity-case-study/data/sample_data_a_document_checklist.csv', 'utf-8');
const { data } = Papa.parse(csv, { header: true, skipEmptyLines: true });
const now = new Date('2026-01-30');

// 1. Count docs with date_received > REFERENCE_NOW
let futureReceived = 0, total = 0;
const futureSamples = {};
for (const row of data) {
  total++;
  if (row.date_received) {
    if (differenceInDays(parseISO(row.date_received), now) > 0) {
      futureReceived++;
      const byStatus = row.document_status;
      futureSamples[byStatus] = (futureSamples[byStatus] || 0) + 1;
    }
  }
}
console.log(`Future date_received: ${futureReceived}/${total} docs (will display "Not yet received")`);
console.log(`  Breakdown by status:`, futureSamples);

// 2. Spot-check: APP-2026-1011 (GreenLeaf Landscaping)
//    On-track. Currently 6 Pending docs (no Under Review, no Expired).
//    Simulate: mark "Business Licenses & Permits" (Pending) as Received.
//    Expected: stays on-track (still too young for Pending rule even if it were stalled), 
//    completeness should rise.
const apps = new Map();
for (const row of data) {
  if (!apps.has(row.application_id)) apps.set(row.application_id, []);
  apps.get(row.application_id).push(row);
}
const docs = apps.get('APP-2026-1011');
const appDate = parseISO(docs[0].application_date);

function compute(docs) {
  const RECEIVED = new Set(['Received', 'Approved', 'Under Review']);
  const PENDING = new Set(['Pending', 'Expired']);
  let r = 0, p = 0, pendStalled = 0, revStalled = 0, exp = 0;
  for (const d of docs) {
    if (RECEIVED.has(d.document_status)) r++;
    if (PENDING.has(d.document_status)) p++;
    if (d.document_status === 'Pending' && differenceInDays(now, appDate) > 14) pendStalled++;
    if (d.document_status === 'Under Review' && d.date_received && differenceInDays(now, parseISO(d.date_received)) > 7) revStalled++;
    if (d.document_status === 'Expired' && d.expiration_date && parseISO(d.expiration_date) <= now) exp++;
  }
  const stalled = pendStalled || revStalled || exp;
  const pct = r + p > 0 ? Math.round(r / (r + p) * 100) : 100;
  return { r, p, pct, stalled: !!stalled, pendStalled, revStalled, exp };
}

console.log(`\n=== Before edit (APP-2026-1011) ===`);
console.log(compute(docs));

const editedDocs = docs.map(d => 
  d.document_type === 'Business Licenses & Permits' ? { ...d, document_status: 'Received' } : d
);

console.log(`\n=== After marking "Business Licenses & Permits" as Received ===`);
console.log(compute(editedDocs));

// 3. Repeat: change all remaining Pending to Received
const allReceivedDocs = docs.map(d => 
  d.document_status === 'Pending' ? { ...d, document_status: 'Received' } : d
);
console.log(`\n=== After marking ALL Pending docs as Received ===`);
console.log(compute(allReceivedDocs));
