import fs from 'fs';
import Papa from 'papaparse';
import { addDays, differenceInDays, parseISO } from 'date-fns';

const csv = fs.readFileSync('/Users/btoomey/newity-case-study/data/sample_data_a_document_checklist.csv', 'utf-8');
const { data } = Papa.parse(csv, { header: true, skipEmptyLines: true });
const now = new Date(2026, 0, 30);

const apps = new Map();
for (const row of data) {
  if (!apps.has(row.application_id)) {
    apps.set(row.application_id, {
      id: row.application_id, business_name: row.business_name,
      app_date: row.application_date, processor: row.assigned_processor,
      loan_amount: parseFloat(row.loan_amount), docs: []
    });
  }
  apps.get(row.application_id).docs.push(row);
}

function derive(app) {
  let p=0, r=0, e=0;
  const appDate = parseISO(app.app_date);
  for (const d of app.docs) {
    if (d.document_status === 'Pending' && differenceInDays(now, appDate) > 14) p++;
    if (d.document_status === 'Under Review' && d.date_received && differenceInDays(now, parseISO(d.date_received)) > 7) r++;
    if (d.document_status === 'Expired' && d.expiration_date && parseISO(d.expiration_date) <= now) e++;
  }
  const reasons = [];
  if (p) reasons.push(`${p} ${p===1?'doc':'docs'} pending >14d`);
  if (r) reasons.push(`${r} ${r===1?'doc':'docs'} under review >7d`);
  if (e) reasons.push(`${e} expired ${e===1?'doc':'docs'}`);
  return { stalled: !!(p||r||e), stalledDocCount: p+r+e, reasons };
}

// Section A
const totalApps = apps.size;
const totalPipeline = Array.from(apps.values()).reduce((s, a) => s + a.loan_amount, 0);
const stalled = Array.from(apps.values()).filter(a => derive(a).stalled).length;
const cutoff = addDays(now, 30);
let expiring = 0;
for (const a of apps.values()) for (const d of a.docs) if (d.expiration_date && parseISO(d.expiration_date) <= cutoff) expiring++;

console.log('=== Section A: Stat cards ===');
console.log(`Active applications: ${totalApps}`);
console.log(`Pipeline value:      $${(totalPipeline/1_000_000).toFixed(1)}M  (raw: $${totalPipeline.toLocaleString()})`);
console.log(`Stalled rate:        ${stalled} of ${totalApps} — ${Math.round(stalled/totalApps*100)}%`);
console.log(`Expiring in 30 days: ${expiring}`);

// Section B
console.log('\n=== Section B: Per-processor (sorted by stalled rate desc) ===');
const procMap = new Map();
for (const a of apps.values()) {
  const cur = procMap.get(a.processor) ?? { total: 0, stalled: 0 };
  cur.total++;
  if (derive(a).stalled) cur.stalled++;
  procMap.set(a.processor, cur);
