            <TableRow>
              <TableHead>Business</TableHead>
              <TableHead>Borrower</TableHead>
              <TableHead>Processor</TableHead>
              <TableHead className="text-right">Loan Amount</TableHead>
              <TableHead>App Date</TableHead>
