            </Link>
          </div>
        </div>
        {dataQualityCount > 0 && (
          <div className="mt-4 border rounded-md p-3 text-sm bg-muted/30">
            <div className="font-medium">Data quality</div>
            <div className="text-muted-foreground mt-1">
              {dataQualityCount} documents are marked &ldquo;Expired&rdquo; but have no
              expiration date. These were excluded from automated stalled
              detection — manual review recommended.
            </div>
          </div>
        )}
